16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "postcode")
48	    private String postcode;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date", columnDefinition = "DATE")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "birth_date", columnDefinition = "DATE")
63	    private LocalDate birthDate;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "membership_number")
69	    private String membershipNumber;
70	
71	    @Column(name = "household_id")
72	    private String householdId;
73	
74	    @Column(name = "namesake_count")
75	    private Integer namesakeCount;
76	
77	    @Column(name = "bulk_signup_warning")
78	    private boolean bulkSignupWarning;
79	
80	    @Column(name = "household_member_count")
81	    private Integer householdMemberCount;
82	
83	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
84	    private Set<Pet> pets;
85	
86	    /**
87	     * Transient, write-only request flag: when {@code true}, creating this owner is allowed even if
88	     * another owner already shares the same last name and address. Never persisted or returned.
89	     */
90	    @Transient
91	    private boolean sharesHousehold;
92	
93	    public String getAddress() {
94	        return this.address;
95	    }
96	
97	    public void setAddress(String address) {
98	        this.address = address;
99	    }
100	
101	    public String getCity() {
102	        return this.city;
103	    }
104	
105	    public void setCity(String city) {
106	        this.city = city;
107	    }
108	
109	    public String getPostcode() {
110	        return this.postcode;
111	    }
112	
113	    public void setPostcode(String postcode) {
114	        this.postcode = postcode;
115	    }
116	
117	    public String getTelephone() {
118	        return this.telephone;
119	    }
120	
121	    public void setTelephone(String telephone) {
122	        this.telephone = telephone;
123	    }
124	
125	    public String getEmail() {
126	        return this.email;
127	    }
128	
129	    public void setEmail(String email) {
130	        this.email = email;
131	    }
132	
133	    public LocalDate getRegistrationDate() {
134	        return this.registrationDate;
135	    }
136	
137	    public void setRegistrationDate(LocalDate registrationDate) {
138	        this.registrationDate = registrationDate;
139	    }
140	
141	    public LocalDate getBirthDate() {
142	        return this.birthDate;
143	    }
144	
145	    public void setBirthDate(LocalDate birthDate) {
146	        this.birthDate = birthDate;
147	    }
148	
149	    /**
150	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
151	     * owner's {@code registrationDate} (falling back to the current date when no registration date
152	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
153	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
154	     */
155	    @Transient
156	    public String getAgeBand() {
157	        if (this.birthDate == null) {
158	            return null;
159	        }
160	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
161	        int age = java.time.Period.between(this.birthDate, reference).getYears();
162	        if (age < 18) {
163	            return "MINOR";
164	        }
165	        if (age < 65) {
166	            return "ADULT";
167	        }
168	        return "SENIOR";
169	    }
170	
171	    public String getCustomerCode() {
172	        return this.customerCode;
173	    }
174	
175	    public void setCustomerCode(String customerCode) {
176	        this.customerCode = customerCode;
177	    }
178	
179	    public String getMembershipNumber() {
180	        return this.membershipNumber;
181	    }
182	
183	    public void setMembershipNumber(String membershipNumber) {
184	        this.membershipNumber = membershipNumber;
185	    }
186	
187	    public String getHouseholdId() {
188	        return this.householdId;
189	    }
190	
191	    public void setHouseholdId(String householdId) {
192	        this.householdId = householdId;
193	    }
194	
195	    public Integer getNamesakeCount() {
196	        return this.namesakeCount;
197	    }
198	
199	    public void setNamesakeCount(Integer namesakeCount) {
200	        this.namesakeCount = namesakeCount;
201	    }
202	
203	    /**
204	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 3, assigned at creation: it
205	     * starts at 1, gains 1 when an email is present, gains 1 when the owner's name was unique at
206	     * creation time ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
207	     */
208	    @Transient
209	    public Integer getMembershipLevel() {
210	        int level = 1;
211	        if (this.email != null && !this.email.isBlank()) {
212	            level++;
213	        }
214	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
215	            level++;
216	        }
217	        return Math.min(level, 3);
218	    }
219	
220	    /**
221	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
222	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
223	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
224	     * has been assigned yet.
225	     */
226	    @Transient
227	    public Integer getCheckDigit() {
228	        if (this.customerCode == null) {
229	            return null;
230	        }
231	        int sum = 0;
232	        boolean dbl = true;
233	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
234	            char c = this.customerCode.charAt(i);
235	            if (c < '0' || c > '9') {
236	                continue;
237	            }
238	            int d = c - '0';
239	            if (dbl) {
240	                d *= 2;
241	                if (d > 9) {
242	                    d -= 9;
243	                }
244	            }
245	            sum += d;
246	            dbl = !dbl;
247	        }
248	        return (10 - (sum % 10)) % 10;
249	    }
250	
251	    /**
252	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners:
253	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone and
254	     * email are already stored in their canonical (E.164 / lower-cased) form, so a {@code null} or
255	     * blank email contributes an empty segment and an absent {@code householdId} an empty segment.
256	     * Two owners are duplicates only when their whole {@code identityKey} is equal.
257	     */
258	    @Transient
259	    public String getIdentityKey() {
260	        String telephonePart = this.telephone == null ? "" : this.telephone;
261	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
262	        String householdPart = this.householdId == null ? "" : this.householdId;
263	        return telephonePart + "|" + emailPart + "|" + householdPart;
264	    }
265	
266	    public boolean isBulkSignupWarning() {
267	        return this.bulkSignupWarning;
268	    }
269	
270	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
271	        this.bulkSignupWarning = bulkSignupWarning;
272	    }
273	
274	    public Integer getHouseholdMemberCount() {
275	        return this.householdMemberCount;
276	    }
277	
278	    public void setHouseholdMemberCount(Integer householdMemberCount) {
279	        this.householdMemberCount = householdMemberCount;
280	    }
281	
282	    public boolean isSharesHousehold() {
283	        return this.sharesHousehold;
284	    }
285	
286	    public void setSharesHousehold(boolean sharesHousehold) {
287	        this.sharesHousehold = sharesHousehold;
288	    }
289	
290	    protected Set<Pet> getPetsInternal() {
291	        if (this.pets == null) {
292	            this.pets = new HashSet<>();
293	        }
294	        return this.pets;
295	    }
296	
297	    protected void setPetsInternal(Set<Pet> pets) {
298	        this.pets = pets;
299	    }
300	
301	    public List<Pet> getPets() {
302	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
303	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
304	        return Collections.unmodifiableList(sortedPets);
305	    }
306	
307	    public void setPets(List<Pet> pets) {
308	        this.pets = new HashSet<>(pets);
309	    }
310	
311	    public void addPet(Pet pet) {
312	        getPetsInternal().add(pet);
313	        pet.setOwner(this);
314	    }
315	
316	    /**
317	     * Return the Pet with the given name, or null if none found for this Owner.
318	     *
319	     * @param name to test
320	     * @return true if pet name is already in use
321	     */
322	    public Pet getPet(String name) {
323	        return getPet(name, false);
324	    }
325	
326	    /**
327	     * Return the Pet with the given name, or null if none found for this Owner.
328	     *
329	     * @param name to test
330	     * @return true if pet name is already in use
331	     */
332	    public Pet getPet(String name, boolean ignoreNew) {
333	        name = name.toLowerCase();
334	        for (Pet pet : getPetsInternal()) {
335	            if (!ignoreNew || !pet.isNew()) {
336	                String compName = pet.getName();
337	                compName = compName.toLowerCase();
338	                if (compName.equals(name)) {
339	                    return pet;
340	                }
341	            }
342	        }
343	        return null;
